    `data-mouth="${face === 'fire' ? 'open' : 'closed'}"`,
    `data-glow="${face === 'fire' ? 1 : 0}"`,
    `data-worried="${face === 'worried' || face === 'sad' ? 1 : 0}"`,
    `data-sleep="${face === 'sleep' ? 1 : 0}"`,
    `data-pose="${face === 'scan' ? 'scan' : face === 'alert' ? 'alert' : ''}"`,
